namespace ghidra.app.plugin.core.datamgr.actions;






using docking;
using docking.widgets.label;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.util.datatype;
using ghidra.program.model.data;
using ghidra.util;
using ghidra.util.data.DataTypeParser;
using ghidra.util.layout;

public class CreateTypeDefDialog : DialogComponentProvider {

	private DataTypeManagerPlugin plugin;
	private Category category;
	private JTextField nameTextField;
	private DataTypeSelectionEditor dataTypeEditor;
	private JTextField categoryField;
	private bool isCancelled;
	private TreePath selectedTreePath;

	CreateTypeDefDialog(DataTypeManagerPlugin plugin, Category category, TreePath treePath) : base("Create TypeDef", true /*modal*/, true /*status*/, true /*buttons*/, false /*tasks*/)
    {
		this.plugin = plugin;
		this.category = category;
		this.selectedTreePath = treePath;

		addWorkPanel(createWorkPanel());

		addOKButton();
		addCancelButton();
	}

	private JComponent createWorkPanel() {

		JPanel panel = new JPanel(new PairLayout());

		// category info
		panel.add(new GLabel("Category:"));
		panel.add(new GLabel(category.getCategoryPath().getPath()));

		// name info
		nameTextField = new JTextField(15);
		panel.add(new GLabel("Name:"));
		panel.add(nameTextField);

		// data type info
		// Note: can't set default DTM for the data type selection field because the dialog allows 
		// switching between destination DTMs
		DataTypeManager dtm = null;
		dataTypeEditor = new DataTypeSelectionEditor(dtm, plugin.getTool(), AllowedDataTypes.ALL);
		panel.add(new GLabel("Data type:"));
		panel.add(dataTypeEditor.getEditorComponent());

		dataTypeEditor.addCellEditorListener(new _Anon_CellEditorListener_1());

		dataTypeEditor.setDefaultSelectedTreePath(selectedTreePath);

		categoryField = new JTextField(24);
		categoryField.setEditable(false);
		categoryField.setName("Category");

		string archiveName = category.getDataTypeManager().getName();
		categoryField.setText(archiveName + category.getCategoryPath().getPath());

		panel.add(new GLabel("Category:"));
		panel.add(categoryField);

		panel.setBorder(BorderFactory.createEmptyBorder(5, 10, 5, 10));

		return panel;
	}

	/* @Override */
	protected void okCallback() {
		// are we valid?
		string name = nameTextField.getText();
		if (name == null || name.isEmpty()) {
			setStatusText("Name required", MessageType.ERROR);
			return;
		}

		if (!DataUtilities.isValidDataTypeName(name)) {
			setStatusText("Invalidate data type name: " + name, MessageType.ERROR);
			return;
		}

		// try to create any required data
		string dtTextValue = dataTypeEditor.getCellEditorValueAsText();
		if (dtTextValue == null || dtTextValue.isEmpty()) {
			setStatusText("Data type required" + dtTextValue, MessageType.ERROR);
			return;
		}

		try {
			if (!dataTypeEditor.validateUserSelection()) {
				setStatusText("Invalidate data type: " + dtTextValue, MessageType.ERROR);
				return;
			}
		}
		catch (InvalidDataTypeException e) {
			setStatusText("Invalidate data type: " + dtTextValue, MessageType.ERROR);
			return;
		}

		DataType dataType = getDataType();
		if (!DataTypeManagerPlugin.isValidTypeDefBaseType(getComponent(), dataType)) {
			setStatusText("Data type cannot be source of a typedef: " + dataType.getName(),
				MessageType.ERROR);
			return;
		}

		clearStatusText();
		close();
	}

	/* @Override */
	protected void cancelCallback() {
		base.cancelCallback();
		isCancelled = true;
	}

	bool isCancelled() {
		return isCancelled;
	}

	string getTypeDefName() {
		if (isCancelled) {
			return null;
		}
		return nameTextField.getText();
	}

	DataType getDataType() {
		DataType dataType = (DataType) dataTypeEditor.getCellEditorValue();
		if (dataType is FunctionDefinition) {
			DataTypeManager dataTypeManager = dataType.getDataTypeManager();
			dataType = PointerDataType.getPointer(dataType, dataTypeManager);
		}
		return dataType;
	}


	internal class _Anon_CellEditorListener_1 : CellEditorListener
	{

			/* @Override */
			public void editingStopped(ChangeEvent e) {
				setStatusText("");
				okCallback();
			}

			/* @Override */
			public void editingCanceled(ChangeEvent e) {
				setStatusText("");
				cancelCallback();
			}
		
	}

}
